273:   /* Apply a batch of A2UI messages. New surfaces mount into `mount`. */
274:   function apply(messages, mount) {
275:     var touched = {};
276:     messages.forEach(function (m) {
277:       var s;
278:       if (m.createSurface) {
279:         s = { id: m.createSurface.surfaceId, catalog: m.createSurface.catalogId, components: {}, data: {} };
280:         s.el = h('div', { class: 'surface', 'data-surface': s.id });
281:         surfaces[s.id] = s;
282:         if (mount) mount.appendChild(s.el);
283:         touched[s.id] = 1;
284:       } else if (m.updateComponents) {
285:         s = surfaces[m.updateComponents.surfaceId];
286:         if (!s) return;
287:         m.updateComponents.components.forEach(function (c) { s.components[c.id] = c; });
288:         touched[s.id] = 1;
289:       } else if (m.updateDataModel) {
290:         s = surfaces[m.updateDataModel.surfaceId];
291:         if (!s) return;
292:         s.data = set(s.data, m.updateDataModel.path, m.updateDataModel.value);
293:         touched[s.id] = 1;
294:       } else if (m.deleteSurface) {
295:         s = surfaces[m.deleteSurface.surfaceId];
296:         if (!s) return;
297:         s.el.remove();
298:         delete surfaces[s.id];
299:         delete touched[s.id];
300:       }
301:     });
302:     Object.keys(touched).forEach(function (id) { if (surfaces[id]) render(surfaces[id]); });
303:   }
